const crypto = require('crypto');
const envelope = $input.first().json;
const request = envelope.body ?? envelope;
const headers = envelope.headers ?? {};
const fail = (message) => { throw new Error(`FCR_FOUNDER_CONTENT_REJECTED: ${message}`); };
const text = (value) => typeof value === 'string' ? value.trim() : '';
const hash = /^[0-9a-f]{64}$/i;
const fullSha = /^[0-9a-f]{40}$/i;
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const orchestration = /^fcr-n8n-social-v2:[0-9a-f]{64}$/i;
const challenge = text(headers['x-fcr-n8n-identity-challenge']).toLowerCase();
const identityContract = text(headers['x-fcr-n8n-identity-contract']);
const expectedWorkflowId = text($env.N8N_FOUNDER_CONTENT_EXPECTED_WORKFLOW_ID);
const expectedFingerprint = text($env.N8N_FOUNDER_CONTENT_EXPECTED_WORKFLOW_FINGERPRINT).toLowerCase();
const expectedRuntimeVersion = text($env.N8N_FOUNDER_CONTENT_EXPECTED_RUNTIME_VERSION);
const identitySecret = text($env.N8N_FOUNDER_CONTENT_IDENTITY_HMAC_SECRET);
if (!request || typeof request !== 'object' || Array.isArray(request)) fail('request body must be an object');
if (request.contract !== 'fcr/n8n-founder-content-orchestration@v1') fail('unsupported contract');
if (request.event !== 'founder-content.schedule.requested') fail('unsupported event');
if (!orchestration.test(text(request.orchestrationId))) fail('invalid orchestration id');
if (!uuid.test(text(request.contentId))) fail('invalid content id');
if (!['linkedin','facebook'].includes(text(request.platform).toLowerCase())) fail('platform not allowed');
if (!text(request.text) || text(request.text).length > 5000) fail('bounded public text is required');
if (!/^jussray\/[A-Za-z0-9._-]+$/.test(text(request.source?.repo))) fail('source repo must be founder-owned');
if (!fullSha.test(text(request.source?.commitSha))) fail('source commit must be exact');
if (request.fcrAuthorization?.mode !== 'exact-current-you') fail('exact Current You authority required');
for (const field of ['authorizationHash','proposalHash','publicPayloadHash']) { if (!hash.test(text(request.fcrAuthorization?.[field]))) fail(`${field} must be a SHA-256 hash`); }
if (!text(request.fcrAuthorization?.currentYouIntentId)) fail('Current You intent id required');
if (!Number.isInteger(request.fcrAuthorization?.currentYouIntentVersion) || request.fcrAuthorization.currentYouIntentVersion < 1) fail('Current You intent version invalid');
if (request.providerRequest?.provider !== 'buffer') fail('only Buffer is enabled');
if (request.providerRequest?.method !== 'schedule') fail('only schedule is enabled');
if (request.providerRequest?.shareNowAllowed !== false) fail('share-now is forbidden');
if (!Number.isFinite(Date.parse(text(request.providerRequest?.scheduleAt)))) fail('scheduleAt must be valid ISO time');
if (request.authority?.orchestrate !== true || request.authority?.requestProviderWrite !== true) fail('orchestration/provider-write authority required');
for (const field of ['authorizePublication','changeCopy','markPublished','readPrivateEvidence']) { if (request.authority?.[field] !== false) fail(`forbidden authority opened: ${field}`); }
if (text(headers['idempotency-key']) !== text(request.orchestrationId)) fail('transport idempotency key mismatch');
if (text(headers['x-fcr-orchestration-contract']) !== request.contract) fail('transport contract mismatch');
if (text(headers['x-fcr-social-provider']).toLowerCase() !== 'buffer') fail('transport provider mismatch');
if (!/^[0-9a-f]{64}$/.test(challenge)) fail('runtime identity challenge required');
if (identityContract !== 'fcr/n8n-founder-content-runtime-identity@v1') fail('runtime identity contract mismatch');
if (expectedWorkflowId !== 'fcrFounderContentV1') fail('runtime workflow id is not pinned');
if (!hash.test(expectedFingerprint)) fail('runtime workflow fingerprint is not pinned');
if (!/^2\.32\.6$/.test(expectedRuntimeVersion)) fail('runtime version must be pinned to 2.32.6');
if (identitySecret.length < 32) fail('runtime identity HMAC secret is not configured');
if (text(headers['x-fcr-n8n-expected-workflow-id']) !== expectedWorkflowId) fail('FCR expected workflow id mismatch');
if (text(headers['x-fcr-n8n-expected-workflow-fingerprint']).toLowerCase() !== expectedFingerprint) fail('FCR expected workflow fingerprint mismatch');
if (text(headers['x-fcr-n8n-expected-runtime-version']) !== expectedRuntimeVersion) fail('FCR expected runtime version mismatch');
const platform = text(request.platform).toLowerCase();
const expectedAlias = platform === 'linkedin' ? 'juss_rayy_linkedin' : 'juss_and_co_facebook';
if (text(request.channel) !== expectedAlias) fail('server-owned Buffer channel alias mismatch');
const bufferChannelId = platform === 'linkedin' ? text($env.BUFFER_FOUNDER_LINKEDIN_CHANNEL_ID) : text($env.BUFFER_FOUNDER_FACEBOOK_CHANNEL_ID);
if (!bufferChannelId) fail(`Buffer channel id is not configured for ${platform}`);
const apiUrl = text($env.BUFFER_API_URL) || 'https://api.buffer.com';
let parsedUrl;
try { parsedUrl = new URL(apiUrl); } catch { fail('Buffer API URL is invalid'); }
const localProof = parsedUrl.protocol === 'http:' && ['127.0.0.1','localhost'].includes(parsedUrl.hostname);
if (parsedUrl.protocol !== 'https:' && !localProof) fail('Buffer API URL must use HTTPS outside local proof');
const q = (value) => JSON.stringify(String(value));
const graphql = `mutation FcrCreateScheduledPost { createPost(input: { text: ${q(request.text)}, channelId: ${q(bufferChannelId)}, schedulingType: automatic, mode: customScheduled, dueAt: ${q(request.providerRequest.scheduleAt)} }) { ... on PostActionSuccess { post { id dueAt } } ... on MutationError { message } } }`;
return [{ json: { request, apiUrl, graphql, bufferChannelId, identity: { challenge, contract: identityContract, workflowId: expectedWorkflowId, workflowFingerprint: expectedFingerprint, runtimeVersion: expectedRuntimeVersion } } }];

const crypto = require('crypto');
const provider = $input.first().json;
const prepared = $('Validate and Prepare Buffer Schedule').first().json;
const createPost = provider?.data?.createPost;
const fail = (message) => { throw new Error(`FCR_BUFFER_SCHEDULE_REJECTED: ${message}`); };
if (Array.isArray(provider?.errors) && provider.errors.length > 0) fail(provider.errors.map((entry) => String(entry?.message ?? 'GraphQL error')).join('; '));
if (!createPost || typeof createPost !== 'object') fail('Buffer createPost response missing');
if (typeof createPost.message === 'string' && createPost.message.trim()) fail(createPost.message.trim());
const post = createPost.post;
if (!post || typeof post.id !== 'string' || !post.id.trim()) fail('Buffer scheduled post id missing');
if (post.dueAt) { const actual = new Date(post.dueAt).toISOString(); const expected = new Date(prepared.request.providerRequest.scheduleAt).toISOString(); if (actual !== expected) fail('Buffer dueAt does not match exact FCR schedule'); }
const identity = prepared.identity;
const secret = String($env.N8N_FOUNDER_CONTENT_IDENTITY_HMAC_SECRET ?? '').trim();
const message = ['fcr/n8n-founder-content-runtime-identity@v1', identity.challenge, identity.workflowId, identity.workflowFingerprint, identity.runtimeVersion, 'fcr/n8n-founder-content-orchestration@v1'].join('\n');
const signature = crypto.createHmac('sha256', secret).update(message).digest('hex');
return [{ json: { orchestrationId: prepared.request.orchestrationId, provider: 'buffer', state: 'scheduled', providerItemId: post.id.trim(), providerRequestId: null, published: false, identity: { ...identity, signature } } }];
